SELECT coalesce(jsonb_agg(
  jsonb_build_array(s.setdatabase::text, s.setrole::text, r.rolname, s.setconfig)
  ORDER BY s.setdatabase, s.setrole
), '[]'::jsonb)
FROM pg_catalog.pg_db_role_setting AS s
LEFT JOIN pg_catalog.pg_roles AS r ON r.oid = s.setrole;

SELECT coalesce(jsonb_agg(
  jsonb_build_array(n.oid::text, n.nspname, pg_catalog.pg_get_userbyid(n.nspowner))
  ORDER BY n.nspname
), '[]'::jsonb)
FROM pg_catalog.pg_namespace AS n;
